style.css:
@-moz-document domain("youtube.com") {
/* =========================
   YouTube Red Theme
   ========================= */

/* ===== Theme Variables ===== */
:root {
  --bg-main: #0b0b0b;
  --bg-secondary: #141414;
  --bg-hover: #1f1f1f;

  --text-primary: #f2f2f2;
  --text-secondary: #b3b3b3;

  --red-primary: #ff2b2b;
  --red-soft: #ff4d4d;
  --red-dark: #990000;

  --border-subtle: #262626;
  --radius: 12px;
}

/* ===== Global ===== */
html, body, ytd-app {
  background-color: var(--bg-main) !important;
  color: var(--text-primary) !important;
  font-family: Inter, Roboto, system-ui, sans-serif;
}

/* ===== Header ===== */
ytd-masthead {
  background: linear-gradient(180deg, #1a0000, var(--bg-secondary)) !important;
  border-bottom: 1px solid var(--border-subtle);
}

/* ===== Sidebar ===== */
ytd-guide-renderer,
ytd-mini-guide-renderer {
  background: var(--bg-secondary) !important;
}

ytd-guide-entry-renderer:hover {
  background: var(--bg-hover) !important;
  border-radius: var(--radius);
}

ytd-guide-entry-renderer[active] {
  background: rgba(255, 43, 43, 0.15) !important;
}

/* ===== Buttons ===== */
yt-button-renderer.style-primary {
  background: linear-gradient(
    135deg,
    var(--red-primary),
    var(--red-dark)
  ) !important;
  color: #fff !important;
  border-radius: var(--radius) !important;
}

/* ===== Video Cards ===== */
ytd-rich-grid-media,
ytd-video-renderer {
  border-radius: var(--radius);
  transition: transform 0.2s ease, box-shadow 0.2s ease;
}

ytd-rich-grid-media:hover,
ytd-video-renderer:hover {
  transform: translateY(-4px);
  box-shadow: 0 12px 35px rgba(255, 43, 43, 0.25);
}

/* ===== Thumbnails ===== */
ytd-thumbnail img {
  border-radius: var(--radius);
}

/* ===== Titles ===== */
#video-title {
  color: var(--text-primary) !important;
}

#video-title:hover {
  color: var(--red-primary) !important;
}

/* ===== Progress Bar ===== */
.ytp-play-progress {
  background: linear-gradient(
    90deg,
    var(--red-soft),
    var(--red-primary)
  ) !important;
}

/* ===== Comments ===== */
ytd-comment-thread-renderer,
ytd-comment-renderer {
  background: var(--bg-secondary) !important;
  border-left: 3px solid var(--red-primary);
  border-radius: var(--radius);
  padding: 14px;
  margin-bottom: 14px;
}

/* ===== Inputs ===== */
input,
textarea {
  background: var(--bg-hover) !important;
  color: var(--text-primary) !important;
  border: 1px solid var(--border-subtle) !important;
  border-radius: var(--radius);
}

/* ===== Scrollbar ===== */
::-webkit-scrollbar {
  width: 10px;
}

::-webkit-scrollbar-thumb {
  background: var(--red-dark);
  border-radius: 10px;
}

::-webkit-scrollbar-thumb:hover {
  background: var(--red-primary);
}
}
